    @Test
    public void testGetVertices_AlreadyComputed() throws Exception {
        // We use reflection to set the 'vertices' field to a non-null value.
        java.lang.reflect.Field field = PolygonsSet.class.getDeclaredField("vertices");
        field.setAccessible(true);
        Vector2D[][] existingVertices = new Vector2D[][]{{new Vector2D(1, 1)}};
        field.set(polygonsSet, existingVertices);

        Vector2D[][] result = polygonsSet.getVertices();

        assertNotNull(result);
